CREATE TABLE IF NOT EXISTS rewards (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,description TEXT NULL,points_cost INT UNSIGNED NOT NULL DEFAULT 0,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_points (user_id BIGINT UNSIGNED PRIMARY KEY,balance INT NOT NULL DEFAULT 0,lifetime_earned INT UNSIGNED DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,points INT NOT NULL,transaction_type ENUM('earned','redeemed','adjusted','expired') NOT NULL,reference_type VARCHAR(60) NULL,reference_id BIGINT UNSIGNED NULL,description VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_redemptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,reward_id BIGINT UNSIGNED NOT NULL,points_spent INT UNSIGNED NOT NULL,status ENUM('pending','approved','fulfilled','cancelled') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,fulfilled_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(reward_id) REFERENCES rewards(id) ON DELETE RESTRICT,INDEX(user_id,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reward_rankings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,period_key VARCHAR(20) NOT NULL,rank_position INT UNSIGNED NOT NULL,points INT NOT NULL,calculated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,period_key),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(period_key,rank_position)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,description TEXT NOT NULL,campaign_type VARCHAR(80) NOT NULL,status ENUM('draft','published','active','completed','cancelled') DEFAULT 'draft',municipality_id BIGINT UNSIGNED NULL,starts_at TIMESTAMP NULL,ends_at TIMESTAMP NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(municipality_id) REFERENCES municipalities(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(status,starts_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS campaign_participants (campaign_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,status ENUM('registered','attended','completed','cancelled') DEFAULT 'registered',joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(campaign_id,user_id),FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS campaign_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,submitted_by BIGINT UNSIGNED NOT NULL,summary TEXT NOT NULL,metrics_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE,FOREIGN KEY(submitted_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS campaign_achievements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,title VARCHAR(150) NOT NULL,description TEXT NULL,awarded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS community_posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(190) NOT NULL,body TEXT NOT NULL,status ENUM('published','hidden','removed') DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(status,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,post_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,body TEXT NOT NULL,status ENUM('published','hidden','removed') DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(post_id) REFERENCES community_posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(post_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reactions (post_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,reaction_type ENUM('like','support','celebrate') DEFAULT 'like',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(post_id,user_id),FOREIGN KEY(post_id) REFERENCES community_posts(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS community_announcements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,body TEXT NOT NULL,created_by BIGINT UNSIGNED NOT NULL,published_at TIMESTAMP NULL,expires_at TIMESTAMP NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(published_at,expires_at)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS drivers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,employee_code VARCHAR(50) UNIQUE NOT NULL,license_number VARCHAR(100) UNIQUE NULL,status ENUM('active','suspended','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vehicles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,registration_number VARCHAR(50) UNIQUE NOT NULL,vehicle_type VARCHAR(80) NOT NULL,municipality_id BIGINT UNSIGNED NULL,status ENUM('active','maintenance','standby','retired') DEFAULT 'active',capacity_kg DECIMAL(12,2) NULL,metadata_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(municipality_id) REFERENCES municipalities(id) ON DELETE SET NULL,INDEX(status,municipality_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vehicle_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vehicle_id BIGINT UNSIGNED NOT NULL,driver_id BIGINT UNSIGNED NULL,task_id BIGINT UNSIGNED NULL,assigned_by BIGINT UNSIGNED NOT NULL,starts_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,ends_at TIMESTAMP NULL,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE,FOREIGN KEY(driver_id) REFERENCES drivers(id) ON DELETE SET NULL,FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE SET NULL,FOREIGN KEY(assigned_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(vehicle_id,ends_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS maintenance_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vehicle_id BIGINT UNSIGNED NOT NULL,maintenance_type VARCHAR(100) NOT NULL,description TEXT NOT NULL,cost DECIMAL(14,2) NULL,status ENUM('scheduled','in_progress','completed','cancelled') DEFAULT 'scheduled',scheduled_at TIMESTAMP NULL,completed_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE,INDEX(vehicle_id,status)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS assets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,asset_code VARCHAR(60) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,asset_type VARCHAR(80) NOT NULL,municipality_id BIGINT UNSIGNED NULL,status ENUM('active','maintenance','lost','retired') DEFAULT 'active',acquired_at DATE NULL,metadata_json JSON NULL,FOREIGN KEY(municipality_id) REFERENCES municipalities(id) ON DELETE SET NULL,INDEX(asset_type,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS asset_tracking (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,asset_id BIGINT UNSIGNED NOT NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,location_text VARCHAR(255) NULL,recorded_by BIGINT UNSIGNED NULL,recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(asset_id) REFERENCES assets(id) ON DELETE CASCADE,FOREIGN KEY(recorded_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(asset_id,recorded_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS asset_conditions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,asset_id BIGINT UNSIGNED NOT NULL,condition_status ENUM('excellent','good','fair','poor','unserviceable') NOT NULL,notes TEXT NULL,inspected_by BIGINT UNSIGNED NULL,inspected_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(asset_id) REFERENCES assets(id) ON DELETE CASCADE,FOREIGN KEY(inspected_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(asset_id,inspected_at)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS contractors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,registration_number VARCHAR(80) UNIQUE NULL,email VARCHAR(190) NULL,phone VARCHAR(40) NULL,status ENUM('pending','active','suspended','terminated') DEFAULT 'pending',sla_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contractor_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,contractor_id BIGINT UNSIGNED NOT NULL,municipality_id BIGINT UNSIGNED NULL,task_id BIGINT UNSIGNED NULL,assigned_by BIGINT UNSIGNED NOT NULL,starts_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,ends_at TIMESTAMP NULL,status ENUM('active','completed','cancelled') DEFAULT 'active',FOREIGN KEY(contractor_id) REFERENCES contractors(id) ON DELETE CASCADE,FOREIGN KEY(municipality_id) REFERENCES municipalities(id) ON DELETE SET NULL,FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE SET NULL,FOREIGN KEY(assigned_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contractor_reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,contractor_id BIGINT UNSIGNED NOT NULL,reviewed_by BIGINT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,comments TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(contractor_id) REFERENCES contractors(id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(contractor_id,created_at)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS document_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) UNIQUE NOT NULL,description TEXT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS document_library (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NULL,upload_id BIGINT UNSIGNED NULL,title VARCHAR(190) NOT NULL,description TEXT NULL,visibility ENUM('public','authenticated','staff','admin') DEFAULT 'authenticated',published_by BIGINT UNSIGNED NOT NULL,published_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES document_categories(id) ON DELETE SET NULL,FOREIGN KEY(upload_id) REFERENCES uploads(id) ON DELETE SET NULL,FOREIGN KEY(published_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(visibility,published_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS document_downloads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,ip_address VARCHAR(45) NULL,downloaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(document_id) REFERENCES document_library(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(document_id,downloaded_at)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS notification_providers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,channel ENUM('email','sms','push') NOT NULL,provider_code VARCHAR(60) NOT NULL,config_json JSON NULL,enabled BOOLEAN DEFAULT FALSE,priority INT DEFAULT 100,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(channel,provider_code)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notification_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,notification_id BIGINT UNSIGNED NULL,channel ENUM('email','sms','push') NOT NULL,recipient VARCHAR(255) NOT NULL,payload_json JSON NOT NULL,status ENUM('queued','processing','delivered','failed','dead') DEFAULT 'queued',attempts INT UNSIGNED DEFAULT 0,max_attempts INT UNSIGNED DEFAULT 3,available_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,locked_at TIMESTAMP NULL,last_error TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(notification_id) REFERENCES notifications(id) ON DELETE SET NULL,INDEX(status,available_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notification_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_id BIGINT UNSIGNED NOT NULL,provider_code VARCHAR(60) NOT NULL,status ENUM('delivered','failed') NOT NULL,response_reference VARCHAR(190) NULL,error_message TEXT NULL,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_id) REFERENCES notification_jobs(id) ON DELETE CASCADE,INDEX(job_id,attempted_at)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS backups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,backup_type ENUM('database','uploads','configuration','full') NOT NULL,schedule_type ENUM('manual','daily','weekly','monthly') DEFAULT 'manual',file_path VARCHAR(500) NOT NULL,file_size BIGINT UNSIGNED NOT NULL DEFAULT 0,sha256 CHAR(64) NULL,status ENUM('running','completed','failed','expired') DEFAULT 'running',retention_until TIMESTAMP NULL,created_by BIGINT UNSIGNED NULL,started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at TIMESTAMP NULL,error_message TEXT NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(status,started_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS restore_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,backup_id BIGINT UNSIGNED NOT NULL,requested_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL,status ENUM('pending','approved','running','completed','failed','rejected') DEFAULT 'pending',reason TEXT NOT NULL,requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at TIMESTAMP NULL,error_message TEXT NULL,FOREIGN KEY(backup_id) REFERENCES backups(id) ON DELETE RESTRICT,FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(status,requested_at)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS upload_scans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,upload_id BIGINT UNSIGNED NOT NULL,scanner_code VARCHAR(60) NOT NULL DEFAULT 'clamav',status ENUM('queued','scanning','clean','infected','error','unavailable') DEFAULT 'queued',signature_name VARCHAR(255) NULL,scanned_at TIMESTAMP NULL,details TEXT NULL,FOREIGN KEY(upload_id) REFERENCES uploads(id) ON DELETE CASCADE,INDEX(status,scanned_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS quarantined_files (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,upload_id BIGINT UNSIGNED NOT NULL,quarantine_path VARCHAR(500) NOT NULL,reason TEXT NOT NULL,quarantined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,released_by BIGINT UNSIGNED NULL,released_at TIMESTAMP NULL,FOREIGN KEY(upload_id) REFERENCES uploads(id) ON DELETE CASCADE,FOREIGN KEY(released_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_sessions (id CHAR(36) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,device_hash CHAR(64) NOT NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(500) NULL,last_seen_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,expires_at TIMESTAMP NOT NULL,revoked_at TIMESTAMP NULL,revoked_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(revoked_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(user_id,revoked_at,expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL,user_id BIGINT UNSIGNED NULL,ip_address VARCHAR(45) NULL,device_hash CHAR(64) NULL,successful BOOLEAN NOT NULL,failure_reason VARCHAR(100) NULL,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(email,attempted_at),INDEX(ip_address,attempted_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS security_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,event_type VARCHAR(100) NOT NULL,severity ENUM('info','low','medium','high','critical') DEFAULT 'info',ip_address VARCHAR(45) NULL,device_hash CHAR(64) NULL,details_json JSON NULL,resolved_at TIMESTAMP NULL,resolved_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(resolved_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(severity,resolved_at,created_at)) ENGINE=InnoDB;
ALTER TABLE users ADD COLUMN failed_login_count INT UNSIGNED NOT NULL DEFAULT 0,ADD COLUMN locked_until TIMESTAMP NULL;

CREATE TABLE IF NOT EXISTS provinces (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,country_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,code VARCHAR(40) NOT NULL,UNIQUE(country_id,code),FOREIGN KEY(country_id) REFERENCES countries(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS communities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ward_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,code VARCHAR(40) NOT NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,UNIQUE(ward_id,code),FOREIGN KEY(ward_id) REFERENCES wards(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS gis_boundaries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,entity_type ENUM('country','province','district','municipality','ward','community') NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,geometry_json JSON NOT NULL,version INT UNSIGNED DEFAULT 1,updated_by BIGINT UNSIGNED NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(entity_type,entity_id),FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS gis_layers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,layer_type ENUM('boundary','marker','heatmap','route') NOT NULL,configuration_json JSON NULL,active BOOLEAN DEFAULT TRUE,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS gis_markers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,layer_id BIGINT UNSIGNED NOT NULL,marker_type VARCHAR(80) NOT NULL,title VARCHAR(190) NOT NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,data_json JSON NULL,status ENUM('active','inactive') DEFAULT 'active',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(layer_id) REFERENCES gis_layers(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,INDEX(layer_id,status),INDEX(latitude,longitude)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS structured_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,log_level ENUM('debug','info','warn','error','critical') NOT NULL,log_type ENUM('application','security','database','queue','upload') NOT NULL,message VARCHAR(500) NOT NULL,context_json JSON NULL,request_id CHAR(36) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(log_type,log_level,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS system_metrics (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,metric_name VARCHAR(100) NOT NULL,metric_value DECIMAL(18,4) NOT NULL,unit VARCHAR(40) NULL,tags_json JSON NULL,recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(metric_name,recorded_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS normalization_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,migration_code VARCHAR(100) UNIQUE NOT NULL,records_migrated INT UNSIGNED NOT NULL DEFAULT 0,details_json JSON NULL,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;

INSERT INTO notification_providers(channel,provider_code,enabled,priority) VALUES ('email','smtp',FALSE,10),('email','sendgrid',FALSE,20),('email','mailgun',FALSE,30),('sms','twilio',FALSE,10),('sms','africas_talking',FALSE,20),('sms','ecoclean_sms',FALSE,30),('push','fcm',FALSE,10),('push','ecoclean_push',FALSE,20) ON DUPLICATE KEY UPDATE priority=VALUES(priority);
INSERT IGNORE INTO reward_points(user_id,balance,lifetime_earned) SELECT id,0,0 FROM users;
INSERT IGNORE INTO document_categories(name,description) VALUES ('Policies','National environmental policies'),('Guides','Operational and citizen guides'),('Reports','Published environmental reports');
